// ── Chord helpers ───────────────────────────────────────────────────────────
const CHORD_RE = /^([A-G](?:#|b)?)(maj7|m7|m|7)?$/
/** 'Am' | 'G7' | 'C#m7' | 'Cmaj7' → app chord object. */
export function chord(symbol, beats) {
  const m = CHORD_RE.exec(symbol)
  if (!m) throw new Error(`bad chord ${symbol}`)
  const [, root, suf = ''] = m
  const c = {
    root,
    quality: suf === 'm' || suf === 'm7' ? 'minor' : 'major',
    extensions: suf === '7' || suf === 'm7' ? ['7'] : suf === 'maj7' ? ['maj7'] : [],
  }
  if (beats) c.beats = beats
  return c
}
/** Bars → chords. A bar "Am F" is two half-bar (2-beat) chords. */
export function barsToChords(bars) {
  return bars.flatMap(bar => {
    const parts = bar.split(' ')
    return parts.length === 1 ? [chord(parts[0])] : parts.map(p => chord(p, 4 / parts.length))
  })
}

// ── Progressions (forms) ────────────────────────────────────────────────────
const rep = (n, bars) => Array.from({ length: n }, () => bars).flat()
const NOTE_ORDER = ['C', 'Db', 'D', 'Eb', 'E', 'F', 'Gb', 'G', 'Ab', 'A', 'Bb', 'B']
const SHARP_KEYS = { 'C#': 'Db', 'D#': 'Eb', 'F#': 'Gb', 'G#': 'Ab', 'A#': 'Bb' }
const up = (root, st, sharps) => {
  const i = NOTE_ORDER.indexOf(SHARP_KEYS[root] || root)
  const n = NOTE_ORDER[(i + st) % 12]
  if (!sharps) return n
  return { Db: 'C#', Eb: 'D#', Gb: 'F#', Ab: 'G#', Bb: 'A#' }[n] || n
}

