/** Chord bars (strings) of a track. */
export function trackBars(track) {
  if (track.form.startsWith('blues12m:')) return blues12(track.form.slice(9), true)
  if (track.form.startsWith('blues12:')) return blues12(track.form.slice(8), false)
  return FORMS[track.form]
}
export const trackChords = (track) => barsToChords(trackBars(track))

